abhinav_35_36 = {
    'hi': '।।6.35--6.36।। श्री अभिनवगुप्त कहते हैं: श्री भगवान् बोले: हे महाबाहो ! इसमें कोई संशय नहीं कि चंचल मन का निग्रह अत्यन्त कठिन है; किन्तु अभ्यास (निरन्तर भगवच्चिन्तन) और वैराग्य (विषय-तृष्णा-त्याग) के द्वारा इसका निग्रह सम्भव है। जिसका मन वश में नहीं है, उसके लिए योग दुष्प्राप्य (कठिन) है; परन्तु वशीकृत मन वाले प्रयत्नशील साधक द्वारा उपायपूर्वक योग सुलभता से सिद्ध किया जा सकता है।',
    'en': '6.35--36 Sri Abhinavagupta states: The Blessed Lord said: Without doubt, O mighty-armed, the restless mind is difficult to restrain; but by constant practice and dispassion it can be brought under control. Yoga is difficult of attainment by one whose mind is uncurbed; but by the self-controlled man who strives, it can be attained by proper means.',
    'be': '৬.৩৫--৬.৩৬ শ্রী অভিনবগুপ্ত বলেছেন: শ্রী ভগবান বললেন: হে মহাবাহো! এতে কোন সং শয় নেই যে চঞ্চল মনের নিগ্রহ অত্যন্ত কঠিন; কিন্তু অভ্যাস (নিরন্তর ভগবচ্চিন্তন) ও বৈরাগ্য (বিষয়-তৃষ্ণা-ত্যাগ) এর দ্বারা এর নিগ্রহ সম্ভব। যার মন বশে নেই, তার জন্য যোগ দুষ্প্রাপ্য (কঠিন); কিন্তু বশীকৃত মন ওয়ালা সচেষ্ট সাধক দ্বারা উপায়পূর্ব ক যোগ সুলভতা থেকে সিদ্ধ করা যেতে পারে।',
    'ka': '೬.೩೫--೬.೩೬ ಶ್ರೀ ಅಭಿನವಗುಪ್ತರು ಹೇಳುತ್ತಾರೆ: ಶ್ರೀ ಭಗವಂತನು ನುಡಿದನು: ಹೇ ಮಹಾಬಾಹೋ! ಚಂಚಲವಾದ ಮನಸ್ಸಿನ ನಿಗ್ರಹವು ಅತ್ಯಂತ ಕಠಿಣವೆಂಬುದರಲ್ಲಿ ಇನ್ಯಾವ ಸಂಶಯವೂ ಇಲ್ಲ; ಆದರೆ ಅಭ್ಯಾಸ (ನಿರಂತರ ಭಗವಚ್ಚಿಂತನೆ) ಹಾಗೂ ವೈರಾಗ್ಯಗಳ (ವಿಷಯತೃಷ್ಣಾತ್ಯಾಗ) ಮೂಲಕ ಇದರ ನಿಗ್ರಹವು ಸಾಧ್ಯ. ಯಾರ ಮನಸ್ಸು ವಶದಲ್ಲಿಲ್ಲವೋ, ಆತನಿಗೆ ಯೋಗವು ದುಷ್ಪ್ರಾಪ್ಯವಾಗಿದೆ (ಕಠಿಣ); ಆದರೆ ವಶೀಕೃತಮನಸ್ಕನಾದ ಪ್ರಯತ್ನಶೀಲಸಾಧಕನಿಂದ ಉಪಾಯಪೂರ್ವಕವಾಗಿ ಯೋಗವನ್ನು ಸುಲಭವಾಗಿ ಸಿದ್ಧಿಸಿಕೊಳ್ಳಬಹುದು'
}

abhinav_37_39 = {
    'hi': '।।6.37--6.39।। श्री अभिनवगुप्त कहते हैं: अर्जुन उवाच—हे कृष्ण ! जो योग में श्रद्धा रखने वाला है, किन्तु प्रयत्नशील न होने के कारण जिसका मन योग से विचलित हो गया है, वह योग-सिद्धि को न पाकर किस गति को जाता है ? हे महाबाहो ! क्या वह कर्ममार्ग और योगमार्ग दोनों से भ्रष्ट होकर छिन्न-भिन्न बादल की भांति निराश्रय होकर नष्ट तो नहीं हो जाता ? हे कृष्ण ! मेरे इस संशय को पूर्ण रूप से दूर करने के लिए आप ही योग्य हैं, क्योंकि आपके सिवा दूसरा कोई इस संशय का छेदन करने वाला नहीं मिल सकता।',
    'en': '6.37--6.39 Sri Abhinavagupta states: Arjuna said: He who possesses faith but lacks self-restraint, whose mind wanders away from Yoga, failing to reach perfection in Yoga—what end does he meet, O Krishna? Fallen from both karma and yoga, unsupported and bewildered on the path of Brahman, does he not perish like a rent cloud, O mighty-armed? You ought to dispel this doubt of mine completely, O Krishna, for there is none other than You who can destroy this doubt.',
    'be': '৬.৩৭--৬.৩৯ শ্রী অভিনবগুপ্ত বলেছেন: অর্জুন উৱাচ—হে কৃষ্ণ! যে যোগে শ্রদ্ধা রাখা ওয়ালা, কিন্তু সচেষ্ট না হওয়ার কারণে যার মন যোগ থেকে বিচলিত হয়ে গেছে, সে যোগ-সিদ্ধিকে না পেয়ে কোন গতিতে যায়? হে মহাবাহো! কি সে কর্মমার্গ ও যোগমার্গ দুটো থেকেই ভ্রষ্ট হয়ে ছিন্ন-বিভিন্ন মেঘের ন্যায় নিরাশয় হয়ে নষ্ট তো হয়ে যায় না? হে কৃষ্ণ! আমার এই সং শয়কে পূর্ণ রূপে দূর করার জন্য আপনিই যোগ্য, কারণ আপনার ছাড়া দ্বিতীয় কেউ এই সং শয়ের ছেদন করা ওয়ালা মিলতে পারে না।',
    'ka': '೬.೩೭--೬.೩೯ ಶ್ರೀ ಅಭಿನವಗುಪ್ತರು ಹೇಳುತ್ತಾರೆ: ಅರ್ಜುನ ಉವಾಚ—ಹೇ ಕೃಷ್ಣ! ಯಾರು ಯೋಗದಲ್ಲಿ ಶ್ರದ್ಧೆಯುಳ್ಳವನಾಗಿದ್ದರೂ ಪ್ರಯತ್ನಶೀಲನಾಗದಿರುವ ಕಾರಣದಿಂದ ಯಾರ ಮನಸ್ಸು ಯೋಗದಿಂದ ವಿಚಲಿತವಾಗಿದೆಯೋ, ಆತನು ಯೋಗಸಿದ್ಧಿಯನ್ನು ಪಡೆಯದೆ ಯಾವ ಗತಿಯನ್ನು ತಲುಪುತ್ತಾನೆ? ಹೇ ಮಹಾಬಾಹೋ! ಆತನು ಕರ್ಮಮಾರ್ಗ ಹಾಗೂ ಯೋಗಮಾರ್ಗಗಳೆರಡರಿಂದಲೂ ಭ್ರಷ್ಟನಾಗಿ ಛಿನ್ನಭಿನ್ನವಾದ ಮೋಡದಂತೆ ನಿರಾಶ್ರಯನಾಗಿ ನಷ್ಟವಾಗಿಹೋಗುವುದಿಲ್ಲವೇ? ಹೇ ಕೃಷ್ಣ! ನನ್ನ ಈ ಸಂಶಯವನ್ನು ಪೂರ್ಣವಾಗಿ ದೂರಗೊಳಿಸಲು ನೀವೇ ಯೋಗ್ಯರು, ಏಕೆಂದರೆ ನಿಮ್ಮನ್ನು ಹೊರತುಪಡಿಸಿ ಇನ್ಯಾರೂ ಈ ಸಂಶಯವನ್ನು ನಿವಾರಿಸುವವರು ಸಿಗಲಾರರು'
}

